from __future__ import annotations

import os
import pathlib
import subprocess
from typing import Dict, List, Optional

import config
from logger import debug, error, fatal, out
from repository import MachineRepository


class DnsmasqManager:
    """Manages dnsmasq configuration and systemd service on openSUSE."""

    @classmethod
    def generate_config(cls) -> str:
        """Generate dnsmasq configuration tailored for MAMA iPXE and static leases."""
        lines: List[str] = [
            "# Automatically generated by MAMA. Do not edit manually.",
            f"interface={getattr(config, 'DHCP_INTERFACE', 'eth1')}",
            "bind-interfaces",
            "# Disable DNS functionality to avoid port 53 conflicts",
            "port=0",
            "",
            "# DHCP Scope",
            (
                f"dhcp-range={config.DHCP_RANGE_START},{config.DHCP_RANGE_END},"
                f"{config.DHCP_NETMASK},{config.DHCP_LEASE_TIME}"
            ),
            f"dhcp-option=option:router,{config.MAMA_HOST}",
            f"dhcp-option=option:dns-server,{config.MAMA_HOST}",
            "",
            "# Network Boot (PXE / iPXE Architecture Matching)",
            "dhcp-match=set:ipxe,175",
            "dhcp-userclass=set:ipxe,iPXE",
            "dhcp-match=set:bios,option:client-arch,0",
            "dhcp-match=set:efi-x86_64,option:client-arch,7",
            "dhcp-match=set:efi-x86_64,option:client-arch,9",
            "dhcp-match=set:efi-arm64,option:client-arch,11",
            "",
            f"dhcp-option=option:server-ip-address,{config.MAMA_HOST}",
            "",
            "# Chainload URLs: boot.py for iPXE; NBP binaries for native firmware PXE",
            f"dhcp-boot=tag:ipxe,http://{config.MAMA_HOST}:8080/boot.py?mac=${{mac}}",
            f"dhcp-boot=tag:!ipxe,tag:bios,undionly.kpxe,,{config.MAMA_HOST}",
            f"dhcp-boot=tag:!ipxe,tag:efi-x86_64,ipxe.efi,,{config.MAMA_HOST}",
            f"dhcp-boot=tag:!ipxe,tag:efi-arm64,ipxe-arm64.efi,,{config.MAMA_HOST}",
            "",
            "# ==========================================================================",
            "# Registered Machines (Static Leases & Hostnames)",
            "#",
            "# Format examples for manual reference:",
            "#   dhcp-host=52:54:00:12:34:56,192.168.2.50,worker01    <- Static IP + Hostname",
            "#   dhcp-host=52:54:00:aa:bb:cc,192.168.2.51             <- Static IP only",
            "#   dhcp-host=52:54:00:dd:ee:ff,worker02                 <- Hostname (dynamic IP)",
            "#",
            "# To persist static IPs through MAMA, set them via the CLI:",
            "#   mama set <machine> ip 192.168.2.50",
            "# ==========================================================================",
        ]

        machines = MachineRepository.get_all()
        for m in machines:
            mac = m.get("mac", "").strip().lower()
            name = m.get("name", "").strip()
            ip = m.get("ip", "").strip()

            if not mac:
                continue

            if ip and name:
                lines.append(f"dhcp-host={mac},{ip},{name}")
            elif ip:
                lines.append(f"dhcp-host={mac},{ip}")
            elif name:
                lines.append(f"dhcp-host={mac},{name}")
            else:
                lines.append(f"dhcp-host={mac}")

        lines.append("")
        return "\n".join(lines)

    @classmethod
    def write_config(cls) -> bool:
        """Write generated configuration to /etc/dnsmasq.d/mama.conf."""
        conf_path = pathlib.Path(getattr(config, "DNSMASQ_CONF_PATH", "/etc/dnsmasq.d/mama.conf"))
        content = cls.generate_config()

        try:
            conf_path.parent.mkdir(parents=True, exist_ok=True)
            conf_path.write_text(content, encoding="utf-8")
            os.chmod(conf_path, 0o644)
            debug(f"[DHCP] Wrote configuration to {conf_path}")
            return True
        except PermissionError:
            error(f"[DHCP] Permission denied writing to {conf_path}. Run with sudo or root.")
            return False
        except Exception as e:
            error(f"[DHCP] Failed writing dnsmasq configuration: {e}")
            return False

    @classmethod
    def test_syntax(cls) -> bool:
        """Validate dnsmasq configuration syntax."""
        conf_path = getattr(config, "DNSMASQ_CONF_PATH", "/etc/dnsmasq.d/mama.conf")
        res = subprocess.run(
            f"dnsmasq --test -C {conf_path}",
            shell=True,
            capture_output=True,
            text=True,
        )
        if res.returncode != 0:
            error(f"[DHCP] dnsmasq syntax test failed: {res.stderr.strip()}")
            return False
        return True

    @classmethod
    def reload_or_restart(cls) -> bool:
        """Reload dnsmasq via SIGHUP if active; otherwise restart the service."""
        if not getattr(config, "DHCP_ENABLED", True):
            return True

        if not cls.write_config():
            return False

        if not cls.test_syntax():
            return False

        status_res = subprocess.run("systemctl is-active --quiet dnsmasq", shell=True)

        if status_res.returncode == 0:
            res = subprocess.run("systemctl reload-or-restart dnsmasq", shell=True)
            if res.returncode == 0:
                debug("[DHCP] dnsmasq service reloaded.")
                return True
            error("[DHCP] Failed to reload dnsmasq.")
            return False
        else:
            res = subprocess.run("systemctl restart dnsmasq", shell=True)
            if res.returncode == 0:
                out("[DHCP] Started dnsmasq service.")
                return True
            error("[DHCP] Failed to start dnsmasq. Check `journalctl -u dnsmasq`.")
            return False

    @classmethod
    def get_active_leases(cls) -> Dict[str, str]:
        """Parse dnsmasq lease database into a MAC -> IP lookup dictionary."""
        lease_file = pathlib.Path(
            getattr(config, "DNSMASQ_LEASES_FILE", "/var/lib/misc/dnsmasq.leases")
        )
        if not lease_file.exists():
            fallback = pathlib.Path("/var/lib/dnsmasq/dnsmasq.leases")
            if fallback.exists():
                lease_file = fallback
            else:
                return {}

        leases: Dict[str, str] = {}
        try:
            for line in lease_file.read_text(encoding="utf-8").splitlines():
                parts = line.strip().split()
                if len(parts) >= 3:
                    mac = parts[1].strip().lower()
                    ip = parts[2].strip()
                    leases[mac] = ip
        except Exception as e:
            debug(f"[DHCP] Could not read leases file: {e}")

        return leases

    @classmethod
    def sync_leases_to_db(cls) -> None:
        """Update any machines lacking an IP in SQLite using active lease data."""
        leases = cls.get_active_leases()
        if not leases:
            return

        for m_data in MachineRepository.get_all():
            mac = m_data.get("mac", "").lower()
            current_ip = m_data.get("ip", "")
            if mac in leases and not current_ip:
                assigned_ip = leases[mac]
                MachineRepository.update_fields(m_data["name"], {"ip": assigned_ip})
                debug(f"[DHCP] Auto-discovered IP {assigned_ip} for {m_data['name']} from DHCP lease")
